entries[29714] = { ["name"] = "Muster: Trommeln der Wiederherstellung", ["text"] = "Benötigt Lederverarbeitung (350)\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Wiederherstellung.\nTrommeln der Wiederherstellung\nBenötigt Lederverarbeitung (350)\nBenutzen: Stellt 15 sec lang insgesamt 600 Gesundheit und Mana bei allen in der Nähe befindlichen Gruppenmitgliedern wieder her. Unwirksam bei Zielen auf Stufe 80 oder höher. (2 Min Abklingzeit)\n50 AufladungenBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppe (4)" }
