entries[30700] = { ["name"] = "Geißelsteinfragmente", ["text"] = "Questgegenstand" }
entries[30701] = { ["name"] = "Oszillierender Schwingungsmesser", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert einen oszillierenden Schwingungsmesser auf dem Boden, der 3.50 min lang aktiv bleibt. Kann nicht innerhalb von 25 Metern um einen anderen Messer platziert werden. Das Schwingungsfeld eines Schwingungsmessers hat einen Radius von 40 Metern. (5 Sek. Abklingzeit)" }
entries[30703] = { ["name"] = "Herbeigezaubertes Bergquellwasser", ["text"] = "Herbeigezauberter Gegenstand\nBenötigt Stufe 60\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 5100 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
